// Check market hours and trading time
const now = new Date();
const hour = now.getHours();
const minute = now.getMinutes();
const day = now.getDay();

// Check if it's a weekday (1-5 = Mon-Fri)
const isWeekday = day >= 1 && day <= 5;

// Market hours: 9:15 AM to 3:30 PM IST
const isMarketHours = (hour > 9 || (hour === 9 && minute >= 15)) && (hour < 15 || (hour === 15 && minute <= 30));

// Safe trading time (avoid first 5 min and last 30 min)
const isSafeTradingTime = isMarketHours && 
                         !(hour === 9 && minute < 20) && 
                         !(hour === 15 && minute > 0);

const result = {
  isWeekday: isWeekday,
  isMarketHours: isMarketHours,
  isSafeTradingTime: isSafeTradingTime,
  canTrade: isWeekday && isMarketHours && isSafeTradingTime,
  currentTime: now.toLocaleString('en-IN', {timeZone: 'Asia/Kolkata'}),
  hour: hour,
  minute: minute,
  day: day
};

return [result];

// Technical Analysis Agent using local data
const nseData = $input.all().find(item => item.json && item.json.records);
const yahooData = $input.all().find(item => item.json && item.json.chart);
const redditData = $input.all().find(item => item.json && item.json.data);

const analysis = {
  timestamp: new Date().toISOString(),
  nifty_data: nseData ? {
    current_level: nseData.json.records?.underlyingValue || 0,
    ce_data: nseData.json.records?.data?.slice(0, 10) || [],
    pe_data: nseData.json.records?.data?.slice(-10) || []
  } : null,
  yahoo_data: yahooData ? {
    current_price: yahooData.json.chart?.result?.[0]?.meta?.regularMarketPrice || 0,
    previous_close: yahooData.json.chart?.result?.[0]?.meta?.previousClose || 0
  } : null,
  reddit_data: redditData ? {
    posts_count: redditData.json.data?.children?.length || 0,
    titles: redditData.json.data?.children?.map(child => child.data?.title).slice(0, 5) || []
  } : null,
  analysis_status: 'completed'
};

return [analysis];

// Signal Generation Logic
const data = $input.first().json;
const currentTime = new Date();

// Extract current NIFTY level
const niftyLevel = data.nifty_data?.current_level || data.yahoo_data?.current_price || 24800;
const atmStrike = Math.round(niftyLevel / 50) * 50;

// Generate sample signals for demonstration
const signals = {
  scalping_signals: [
    {
      signal_id: `SCALP_NIFTY_${currentTime.getTime()}`,
      strike: atmStrike,
      option_type: 'CE',
      expiry_date: currentTime.toISOString().split('T')[0],
      action: 'BUY',
      entry_price: 120.5,
      stop_loss: 95.0,
      target_1: 155.0,
      target_2: 180.0,
      risk_reward_ratio: 1.35,
      setup_type: 'BREAKOUT',
      rationale: ['ATM breakout setup', 'High volume confirmation'],
      valid_until: new Date(currentTime.getTime() + 45*60*1000).toISOString()
    }
  ],
  swing_signals: [
    {
      signal_id: `SWING_NIFTY_${currentTime.getTime()}`,
      instrument: 'NIFTY',
      current_price: niftyLevel,
      action: 'BUY',
      entry_price: niftyLevel,
      stop_loss: niftyLevel * 0.98,
      target_1: niftyLevel * 1.025,
      target_2: niftyLevel * 1.045,
      risk_reward_ratio: 1.25,
      holding_period: '2-3 days',
      rationale: ['Technical breakout', 'Positive sentiment']
    }
  ],
  market_analysis: data,
  generation_time: currentTime.toISOString()
};

return [signals];

// Risk Management Validation
const signals = $input.first().json;
const maxRiskAmount = 2000; // Max risk per trade
const maxRiskPercent = 2; // 2% max risk

const validateSignal = (signal) => {
  const risk = Math.abs(signal.entry_price - signal.stop_loss);
  const reward = Math.abs(signal.target_1 - signal.entry_price);
  const rr = risk > 0 ? reward / risk : 0;

  const riskAmount = risk * 50; // 1 lot = 50 units

  const isValid = 
    rr >= 1.5 && // Min RR ratio
    riskAmount <= maxRiskAmount && // Max risk amount
    signal.entry_price > 0 && // Valid entry price
    signal.stop_loss > 0 && // Valid stop loss
    signal.target_1 > 0; // Valid target

  return {
    ...signal,
    validation_status: isValid ? 'APPROVED' : 'REJECTED',
    risk_amount: riskAmount,
    risk_reward_calculated: rr,
    validation_reason: isValid ? 'Passed all checks' : 'Failed risk criteria'
  };
};

const validated = {
  scalping_signals: signals.scalping_signals.map(validateSignal),
  swing_signals: signals.swing_signals.map(validateSignal),
  approved_count: 0,
  total_risk: 0,
  validation_time: new Date().toISOString()
};

// Count approved signals
validated.approved_count = 
  validated.scalping_signals.filter(s => s.validation_status === 'APPROVED').length +
  validated.swing_signals.filter(s => s.validation_status === 'APPROVED').length;

// Calculate total risk
validated.total_risk = 
  [...validated.scalping_signals, ...validated.swing_signals]
  .filter(s => s.validation_status === 'APPROVED')
  .reduce((sum, s) => sum + s.risk_amount, 0);

return [validated];

// Format alerts for different channels
const data = $input.first().json;
const currentTime = new Date();

const formatSignal = (signal) => {
  if (signal.validation_status !== 'APPROVED') return null;

  return `🎯 ${signal.strike ? `NIFTY ${signal.strike}${signal.option_type}` : signal.instrument}\n` +
         `💰 Entry: ₹${signal.entry_price}\n` +
         `🛡️ SL: ₹${signal.stop_loss}\n` +
         `🎯 T1: ₹${signal.target_1}\n` +
         `⚖️ RR: 1:${signal.risk_reward_calculated?.toFixed(1)}\n` +
         `💼 Risk: ₹${signal.risk_amount?.toFixed(0)}`;
};

const approvedScalping = data.scalping_signals.filter(s => s.validation_status === 'APPROVED');
const approvedSwing = data.swing_signals.filter(s => s.validation_status === 'APPROVED');

let telegramMessage = `🚀 **AI TRADING SIGNALS** - ${currentTime.toLocaleString('en-IN', {timeZone: 'Asia/Kolkata'})}\n\n`;

if (approvedScalping.length > 0) {
  telegramMessage += `⚡ **SCALPING SIGNALS:**\n\n`;
  approvedScalping.forEach((signal, index) => {
    const formatted = formatSignal(signal);
    if (formatted) telegramMessage += `**${index + 1}.** ${formatted}\n\n`;
  });
}

if (approvedSwing.length > 0) {
  telegramMessage += `📊 **SWING SIGNALS:**\n\n`;
  approvedSwing.forEach((signal, index) => {
    const formatted = formatSignal(signal);
    if (formatted) telegramMessage += `**${index + 1}.** ${formatted}\n\n`;
  });
}

telegramMessage += `🔒 **Total Risk: ₹${data.total_risk?.toFixed(0)}**\n`;
telegramMessage += `⚠️ **Max 2% risk per trade | Square off by 3:25 PM**\n\n`;
telegramMessage += `#TradingSignals #NIFTY #AI`;

const alerts = {
  telegram_message: telegramMessage,
  email_subject: `🎯 AI Trading Signals - ${data.approved_count} Opportunities`,
  email_body: telegramMessage.replace(/\*\*/g, ''),
  whatsapp_message: telegramMessage.substring(0, 1000) + '...',
  signal_count: data.approved_count,
  total_risk: data.total_risk
};

return [alerts];
